export const teamByBatch = (batch: number) => team.filter((m) => m.batch === batch);
export const teamByVertical = (v: Member["vertical"]) => team.filter((m) => m.vertical === v);
export const porHolders = team.filter((m) => m.isPorHolder || m.designation);
export const batches = [...new Set(team.map((m) => m.batch))].sort((a, b) => b - a);
